// Builds actions_array for the currently selected type from the Edvin API payload.

const CONTACT_REASON_BY_ZENDESK = {
  "contact_reason__rebooking": "Rebooking",
  "contact_reason__cancellation": "Cancellation",
  "contact_reason__refund": "Refund",
  "contact_reason__name_correction_change": "Name Correction/Change",
  "contact_reason__add_passenger": "Add Passenger/New ticket sell",
  "contact_reason__change_customers_personal_information": "Change customer's personal information",
  "contact_reason__document_travel_info": "Document & Travel Info",
  "contact_reason__payment_question": "Payment Question",
  "contact_reason__ancillaries_products": "Ancillaries/Services & Products",
  "contact_reason__unconfirmed_booking": "Unconfirmed booking",
  "contact_reason__site_support": "Site support",
  "contact_reason__ongoing_issues": "Ongoing issues",
  "contact_reason__other": "Other",
  // SCHEDULE CHANGE //
  "contact_reason__schedule_change": "Rebooking",
  "contact_reason__cancellation_sc": "Cancellation",
  "contact_reason__self_transfer_guarantee_vi_sc": "Self Transfer Guarantee (VI) - SC",
  "contact_reason__self_transfer_guarantee_vi_passengers_at_the_airport": "Self Transfer Guarantee (VI) - Passengers at the airport",
  "contact_reason__refund_sc": "Refund",
  "contact_reason__ancillaries_products_sc": "Ancillaries/Services & Products",
  "contact_reason__document_travel_info_sc": "Document & Travel Info",
  "contact_reason__other_sc": "Other"
};
const CONTACT_REASON = CONTACT_REASON_BY_ZENDESK[ZT.getVariableValue("custom_field_29559177650834", "Cancellation")] || "";

let type_id = ZT.getVariableValue("type", "");
let selected_type = transforms.category.types.find(x => x.id == type_id);

let { channel, category } = transforms;
const type = selected_type.name;
const ids = { channelId: channel.id, categoryId: category.id, typeId: type_id };

// Edvin returns bucket as { id, name }. Match on id first - it's the stable
// contract, while the label is display text ETG can reword any time.
// KEEP THIS BLOCK IDENTICAL IN NODES 2 AND 46 - both feed node 27's routing.
const BUCKET_BY_ID = { 3: "no_action", 4: "proceed", 5: "different_request" };

const BUCKET_BY_NAME = {
  "no action": "no_action",
  "no_action": "no_action",
  "do not proceed": "no_action",
  "proceed": "proceed",
  "different request": "different_request",
  "different_request": "different_request"
};

const BUCKET_NAME_KEYS = ["name", "value", "key", "label", "code", "slug", "type", "bucketKey"];

function rawBucketName(b) {
  if (typeof b === "string") return b;
  for (let i = 0; i < BUCKET_NAME_KEYS.length; i++) {
    const v = b[BUCKET_NAME_KEYS[i]];
    if (typeof v === "string" && v.trim() !== "") return v;
  }
  return "";
}

function bucketKey(b) {
  if (b.id != null && BUCKET_BY_ID[b.id]) return BUCKET_BY_ID[b.id];
  const raw = rawBucketName(b);
  if (!raw) return "";
  return BUCKET_BY_NAME[raw.trim().toLowerCase()] || raw;
}

const actions_array = selected_type.actions.map(action => ({
  ...action,
  bucket: bucketKey(action.bucket),
  bucketId: action.bucket && action.bucket.id,
  actionId: action.id
}));

ZT.setTransformData("actions_array", actions_array);

let current_pnr = {
  ...transforms.current_pnr,
  channel: channel.name,
  channelId: ids.channelId,
  category: category.name,
  categoryId: ids.categoryId,
  type,
  typeId: ids.typeId,
  notes,
  actions_array
};

let customer_action_pnrs = transforms.customer_action_pnrs || [];
let existingIndex = customer_action_pnrs.findIndex(p => p.pnr === current_pnr.pnr);
if (existingIndex >= 0) {
  customer_action_pnrs[existingIndex] = current_pnr;
} else {
  customer_action_pnrs.push(current_pnr);
}
ZT.setTransformData("customer_action_pnrs", customer_action_pnrs);

