27.content:
let customer_action_pnrs = transforms.customer_action_pnrs || [];

function findAction(item, selectedValue) {
  const wanted = String(selectedValue);
  return item.actions_array.find(a =>
    String(a.actionId) === wanted || String(a.id) === wanted || String(a.name) === wanted
  );
}

let unresolved_selections = [];
let resolved_pnrs = [];

customer_action_pnrs.forEach((item, index) => {
  const variableName = "customer_action_" + item.pnr + "_" + index;
  const rawSelection = ZT.getVariableValue(variableName, "");
  const selectedAction = findAction(item, rawSelection);

  if (!selectedAction || !selectedAction.bucket) {
    unresolved_selections.push({ pnr: item.pnr, type: item.type });
    return;
  }

  resolved_pnrs.push({
    ...item,
    customer_action: selectedAction.name,
    actionId: selectedAction.actionId,
    bucket: selectedAction.bucket,
    bucketId: selectedAction.bucketId,
    edvin_actions: selectedAction.edvin_actions
  });
});

function buildUnresolvedHtml(rows) {
  let html = '<div style="font-family:Arial,sans-serif;background:#fff7ed;border:1px solid #fed7aa;border-radius:14px;padding:16px 18px;">';
  html += '<h3 style="margin:0 0 6px;font-size:16px;color:#7c2d12;">The customer action did not come through</h3>';
  html += '<p style="margin:0 0 12px;font-size:14px;line-height:1.5;color:#7c2d12;">Nothing has been recorded for this order yet - no tickets, no errand in Edvin. Pick the action again for the PNR(s) below and continue.</p>';
  html += '<ul style="margin:0;padding-left:18px;">';
  rows.forEach(row => {
    html += '<li style="font-size:14px;line-height:1.6;color:#7c2d12;"><span style="font-weight:700;">' + row.pnr + '</span> (' + row.type + ')</li>';
  });
  html += '</ul></div>';
  return html;
}

const errandKey = item => item.type + "|" + item.customer_action;
const isProceed = item => item.bucket.toLowerCase() === "proceed";
const joinPnrs = items => [...new Set(items.map(i => i.pnr))].join(", ");
function mergePassengers(items) {
  const unique = [];
  const seen = new Set();
  items.forEach(item => {
    (item.passengers || []).forEach(p => {
      const key = (p.passengerFirstName || "") + "|" + (p.passengerLastName || "");
      if (!seen.has(key)) {
        seen.add(key);
        unique.push(p);
      }
    });
  });
  return unique;
}
// Same shape as mergePassengers/joinPnrs: one errand can carry N PNRs, so its
// agent notes have to carry all N too. PNR-prefixed so Edvin/the agent can tell
// whose note is whose; de-duped so two PNRs with identical text (or both blank)
// don't repeat. See buildFinalErrandRecord below - this is the same "notes"
// field the 2026-08-21 fix (ZD 337619) missed, reported again 2026-08-24.
function mergeNotes(items) {
  const seen = new Set();
  const parts = [];
  items.forEach(item => {
    const note = (item.notes || "").trim();
    if (note && !seen.has(note)) {
      seen.add(note);
      parts.push(item.pnr + ": " + note);
    }
  });
  return parts.join(" | ");
}

function groupByErrand(items) {
  const map = new Map();
  items.forEach(item => {
    const key = errandKey(item);
    if (!map.has(key)) map.set(key, []);
    map.get(key).push(item);
  });
  return [...map.values()];
}

function toGrandchild(item, pnrList) {
  return {
    title: "Grandchild Ticket: " + pnrList,
    pnr: pnrList,
    bucket: item.bucket,
    category: item.category,
    customer_action: item.customer_action,
    type: item.type,
    channel: item.channel,
    contact_reason: item.category,
    genesys_interaction_type: item.genesys_interaction_type
  };
}

function buildChildTickets(pnrs) {
  const childTickets = [];
  const proceed = pnrs.filter(isProceed);
  const nonProceed = pnrs.filter(item => !isProceed(item));

  if (proceed.length) {
    const combos = groupByErrand(proceed);
    const childTicket = {
      title: "Child Ticket: " + joinPnrs(proceed),
      pnr: joinPnrs(proceed),
      bucket: proceed[0].bucket,
      category: proceed[0].category,
      customer_action: proceed[0].customer_action,
      type: proceed[0].type,
      passengers: mergePassengers(proceed),
      grandchild_tickets: []
    };

    if (combos.length > 1) {
      childTicket.grandchild_tickets = combos.map(group => {
        const pnrList = joinPnrs(group);
        const grandchild = toGrandchild(group[0], pnrList);
        grandchild.passengers = mergePassengers(group);
        return grandchild;
      });
    }

    childTickets.push({ child_ticket: childTicket });
  }

  groupByErrand(nonProceed).forEach(group => {
    childTickets.push({
      child_ticket: {
        title: "Silent Ticket: " + joinPnrs(group),
        pnr: joinPnrs(group),
        bucket: group[0].bucket,
        category: group[0].category,
        customer_action: group[0].customer_action,
        type: group[0].type,
        passengers: mergePassengers(group),
        grandchild_tickets: []
      }
    });
  });

  childTickets.sort((a, b) => Number(isProceed(a.child_ticket)) - Number(isProceed(b.child_ticket)));

  return childTickets;
}

function buildChildTicketsNote(childTickets) {
  const childCount = childTickets.filter(ct => isProceed(ct.child_ticket)).length;
  const silentCount = childTickets.filter(ct => !isProceed(ct.child_ticket)).length;
  const grandchildCount = childTickets.reduce((sum, ct) => sum + ct.child_ticket.grandchild_tickets.length, 0);

  let note = "(Child Tickets: " + childCount + ", Grand Child Tickets: " + grandchildCount + ", Silent Tickets: " + silentCount + ")\n\n";

  childTickets.forEach(ct => {
    const t = ct.child_ticket;
    const label = isProceed(t) ? "Child Ticket" : "Silent Ticket";

    note += "**" + label + "**: " + t.pnr + ",\n  **Contact Reason**: " + t.category + ",\n  **Type**: " + t.type + ",\n  **Customer Action**: " + t.customer_action + "\n";

    t.grandchild_tickets.forEach(gc => {
      note += "  - **Grandchild Ticket**: " + gc.pnr + ", Action: " + gc.customer_action + ", Contact Reason: " + gc.contact_reason + ", Genesys Interaction Type: " + gc.genesys_interaction_type + "\n";
    });

    note += "\n";
  });

  return note.trim();
}

let child_tickets = buildChildTickets(resolved_pnrs);

let planned_ticket_titles = [];
child_tickets.forEach(ct => {
  planned_ticket_titles.push(ct.child_ticket.title);
  ct.child_ticket.grandchild_tickets.forEach(gc => planned_ticket_titles.push(gc.title));
});

// ERRAND RECORD (fixed 2026-08-21, ZD 337619 / today's ETG pre-launch call;
// notes field fixed 2026-08-24):
// group[0] alone used to become the Edvin errand record, so when 2+ PNRs share the
// same (type + customer_action) pair and collapse into ONE errand, every PNR after
// the first silently disappeared from that errand's message - Christina caught this
// on ticket 337619 (IFVLYF + PN6WPN, both Void / Void completed, only IFVLYF made it
// into the Edvin free text). An errand covering N PNRs must carry all N, the same way
// the child/silent ticket built two blocks up already does (joinPnrs, formatted_passengers
// join). buildFinalErrandRecord is that combination step, kept separate from
// groupByErrand itself so "which PNRs share an errand" (the key, identical to the
// ticket grouping above) and "what that errand's combined record looks like" (this)
// stay two readable steps instead of one dense one.
// The 2026-08-21 pass combined pnr/passengers/orderReference but left `notes` as an
// untouched spread of group[0] - so a second PNR's agent notes were silently dropped
// from the "Agent Notes" line node 44 builds for Edvin whenever two PNRs collapsed
// into one errand. mergeNotes (above) closes that gap the same way mergePassengers
// already does for passengers.
function buildFinalErrandRecord(group) {
  const uniquePassengers = mergePassengers(group);

  const orderReferences = [...new Set(group.map(item => item.orderReference).filter(Boolean))];

  return {
    ...group[0],
    pnr: joinPnrs(group),
    passengers: uniquePassengers,
    formatted_passengers: [...new Set(group.map(item => item.formatted_passengers))].join(""),
    orderReference: orderReferences.join(", ") || group[0].orderReference,
    providerBookingIds: JSON.stringify(group.map(item => item.id).filter(id => id != null)),
    notes: mergeNotes(group)
  };
}

let final_pnrs = groupByErrand(resolved_pnrs).map(buildFinalErrandRecord);
let child_tickets_note = buildChildTicketsNote(child_tickets);

ZT.setTransformData("customer_action_pnrs", resolved_pnrs);
ZT.setFormData("has_unresolved_selections", unresolved_selections.length > 0);
