// Cursor over transforms.child_tickets. Node 33 creates the Zendesk child/silent
// ticket right after this node, so this node stages that request's payload.
// Grandchildren run through their own dedicated body (36 -> 37 -> ... -> 72),
// reusing the same connected objects (CO #157/#181/#201) via separate nodes.

let is_more_child_tickets = true;
