if (child_tickets_count >= child_tickets.length) child_tickets_count = 0;

let current_child_ticket = child_tickets[child_tickets_count].child_ticket;

// Loop counter for the agent-facing confirmation card (node 84): 1-based position
// of the ticket about to be created, out of the total this run will create.
let child_ticket_display_index = child_tickets_count + 1;
