ZT.setFormData("child_ticket_display_index", child_ticket_display_index);
ZT.setFormData("child_tickets_total", child_tickets_total);

// Idempotency guard: tracks tickets ATTEMPTED (recorded here, before node 33 fires),
// not just ones confirmed created, so a create that succeeded but reported badly
// still counts as done and doesn't get retried into a duplicate. Node 34 skips the
// create call at node 33 when child_ticket_already_created is true. Keys are cleared
// by node 10 (fresh start / Restart) and node 29 (Additional / Different Request
// re-entry), so a genuinely new pass over the same PNRs is never suppressed.
let attempted_child_ticket_keys = transforms.attempted_child_ticket_keys || [];
let child_ticket_already_created = attempted_child_ticket_keys.includes(current_child_ticket.title);
ZT.setFormData("child_ticket_already_created", child_ticket_already_created);

if (!child_ticket_already_created) {
