function buildErrandCardHtml(payload, ticketFields) {
  ticketFields = ticketFields || {};

  function esc(s) {
    if (s === null || s === undefined) return "";
    return String(s)
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;");
  }

  function humanize(v) {
    if (!v) return "";
    var parts = String(v).split("__");
    var last = parts[parts.length - 1].replace(/_/g, " ");
    return last.replace(/\b\w/g, function (c) { return c.toUpperCase(); });
  }

  function row(label, value) {
    if (value === null || value === undefined || value === "") return "";
    return '<div style="margin:6px 0;font-size:13px;">' +
      '<span style="color:#6b7280;font-weight:600;">' + esc(label) + ':</span> ' +
      '<span style="color:#111827;">' + esc(value) + '</span></div>';
  }

  function heading(text) {
    return '<div style="margin-top:14px;margin-bottom:4px;font-weight:700;font-size:12px;' +
      'color:#374151;text-transform:uppercase;letter-spacing:0.03em;">' + esc(text) + '</div>';
  }

  var title = payload.title || ("PNR " + (payload.pnr || ""));

  var passengersHtml;
  if (payload.passengers && payload.passengers.length) {
    passengersHtml = payload.passengers.map(function (p) {
      var first = p.passengerFirstName || p.first_name || p.firstName || "";
      var last = p.passengerLastName || p.last_name || p.lastName || "";
      return row("First Name", first) + row("Last Name", last);
    }).join('<div style="border-top:1px solid #f3f4f6;margin:8px 0;"></div>');
  } else {
    passengersHtml = '<div style="color:#9ca3af;font-size:13px;font-style:italic;">No passenger details available</div>';
  }

  var html =
    '<div style="font-family:Arial,Helvetica,sans-serif;max-width:420px;border:1px solid #e5e7eb;' +
    'border-radius:8px;padding:14px 16px;background:#ffffff;">' +

    '<div style="font-size:15px;font-weight:700;color:#111827;margin-bottom:2px;">' + esc(title) + '</div>' +
    (payload.type || payload.category
      ? '<div style="font-size:12px;color:#6b7280;margin-bottom:6px;">' +
      esc(payload.type) + (payload.category ? ' · ' + esc(payload.category) : '') + '</div>'
      : '') +

    row("Bucket", payload.bucket) +
    row("PNR", payload.pnr) +
    row("Customer Action", payload.customer_action) +
    row("Contact Reason", humanize(payload.contact_reason)) +
    row("Channel", payload.channel) +

    heading("Ticket Info") +
    row("Order Reference", ticketFields.order_reference) +
    row("Ticket Contact Reason", humanize(ticketFields.ticket_contact_reason)) +
    row("Conversation ID", ticketFields.conversation_id) +
    row("Conversation Type", humanize(ticketFields.conversation_type)) +

    heading("Passengers") +
    passengersHtml +

    '</div>';

  return html;
}

